21:  const Slot = React.forwardRef<HTMLElement, SlotProps>((props, forwardedRef) => {
22:    let { children, ...slotProps } = props;
23:    let slottableElement: React.ReactElement | null = null;
24:    let hasSlottable = false;
25:    const newChildren: React.ReactNode[] = [];
26:
27:    if (isLazyComponent(children) && typeof use === 'function') {
28:      children = use(children._payload);
29:    }
30:
31:    React.Children.forEach(children, (maybeSlottable) => {
32:      if (isSlottable(maybeSlottable)) {
33:        hasSlottable = true;
34:        const slottable = maybeSlottable;
35:        let child = 'child' in slottable.props ? slottable.props.child : slottable.props.children;
36:
37:        if (isLazyComponent(child) && typeof use === 'function') {
38:          child = use(child._payload);
39:        }
40:
41:        slottableElement = getSlottableElementFromSlottable(slottable, child);
42:        newChildren.push((slottableElement?.props as any)?.children);
43:      } else {
44:        newChildren.push(maybeSlottable);
45:      }
46:    });
47:
48:    if (slottableElement) {
49:      slottableElement = React.cloneElement(slottableElement, undefined, newChildren);
50:    } else if (
51:      // A `Slottable` was found but it didn't resolve to a single element (e.g.
52:      // it wrapped multiple elements, text, or a render-prop `child` that
53:      // wasn't an element). Don't fall back to treating the `Slottable` wrapper
54:      // itself as the slot target — throw a descriptive error below instead.
55:      !hasSlottable &&
56:      React.Children.count(children) === 1 &&
57:      React.isValidElement(children)
58:    ) {
59:      slottableElement = children;
60:    }
61:
62:    if (!slottableElement) {
63:      // Empty/falsy children (`null`, `undefined`, `false`, no children, etc.) are valid and
64:      // render nothing. Anything else is content we couldn't slot onto a single element, which
65:      // is a usage error, so we fail loudly with a clear message.
66:      if (children || children === 0) {
67:        throw new Error(
68:          hasSlottable ? createSlottableError(ownerName) : createSlotError(ownerName),
69:        );
70:      }
71:      return children;
72:    }
73:
74:    const slottableElementRef = getElementRef(slottableElement);
75:    const composedRefs = composeRefs(forwardedRef, slottableElementRef);
76:    const mergedProps = mergeProps(slotProps, slottableElement.props ?? {});
77:
78:    // do not pass ref to React.Fragment for React 19 compatibility
79:    if (slottableElement.type !== React.Fragment) {
80:      mergedProps.ref = forwardedRef ? composedRefs : slottableElementRef;
81:    }
82:
83:    return React.cloneElement(slottableElement, mergedProps);
84:  });
85:
86:  Slot.displayName = `${ownerName}.Slot`;
87:  return Slot;
88:}
